        "function": "Helps skin hold onto water",
        "proposed_label": "Helps moisturize",
        "short_intro": "Panthenol helps skin hold moisture and feel softer. It is a useful supporting ingredient in a moisturizer for dry skin.",
        "depth": "You may see it called provitamin B5. Its water-holding job is called humectancy. It can also help ingredients dissolve, so it contributes both to skin feel and to how a product is made.",
        "evidence_note": "Its water-holding, skin-conditioning and dissolving roles are documented in the published final cosmetic assessment.",
