        "editorial_status": "user_approved",
        "function": "Holds moisture and can help surface skin shed",
        "proposed_label": "Moisturizes and smooths texture",
        "short_intro": "Lactic acid can help hold moisture and, in an exfoliating formula, smooth the skin’s surface. It can also adjust a product’s acidity.",
        "depth": "Like glycolic acid, it belongs to the AHA family. Its presence alone does not make a product a peel: the amount, acidity and whole formula determine how much skin shedding to expect.",
        "evidence_note": "The ingredient reference supports water holding and acidity control; FDA supports the AHA skin-shedding explanation.",
        "cautions": {
          "standalone_text": "Follow the AHA sun-protection guidance: sunscreen, protective clothing and limited sun exposure during use and for a week afterward. This is FDA’s AHA guidance, not a lactic-acid-specific trial result.",
          "embedded_statements": [],
          "null_meaning": "No standalone caution was written in this approved entry; this is not an assurance of universal tolerance."
        },
